kit.scene('devotion', {
  init(kit) {
    const O = W.O;
    let garland = '';
    for (let i = 0; i <= 16; i++) { const k = i / 16, x = 60 + k * 798, y = 70 + Math.sin(k * Math.PI) * 90; garland += '<circle cx="' + x.toFixed(0) + '" cy="' + y.toFixed(0) + '" r="14" style="fill:' + (i % 2 ? 'var(--gold)' : 'var(--red)') + ';' + O + '"/>'; }
    const lamp = '<g class="devotion-lamp"><circle class="devotion-halo" cx="170" cy="820" r="220" style="fill:var(--second);opacity:.3"/>' +
      '<path d="M90 900 Q170 960 250 900 Q240 870 170 872 Q100 870 90 900 Z" style="fill:var(--goldDeep);' + O + '"/>' +
      '<path class="devotion-flame" d="M170 870 Q146 840 170 790 Q194 840 170 870 Z" style="fill:var(--gold);stroke:var(--accent);stroke-width:3"/>' +
      '<path d="M120 930 L220 930 L200 1027 L140 1027 Z" style="fill:var(--goldDeep);' + O + '"/></g>';
    this.s = W.shot(kit, {
      id: 'devotion', glow: true, back: '<rect width="918" height="1027" style="fill:var(--second);opacity:.25"/>' + garland,
      cast: [{ who: 'ravana', x: 600, y: 1620, s: 1.28 }],
      front: lamp,
      cam: [1.0, 1.04, 459, 520, 459, 505],
      arm: () => 46,
      lines: [],
      extra: (t, stage) => {
        if (!this.fl) { this.fl = stage.querySelector('.devotion-flame'); this.ha = stage.querySelector('.devotion-halo'); }
        const f = 1 + 0.08 * Math.sin(t * 7) + 0.05 * Math.sin(t * 11.3);
        this.fl.setAttribute('transform', 'translate(170 870) scale(' + (2 - f).toFixed(3) + ' ' + f.toFixed(3) + ') translate(-170 -870)');
        this.ha.style.opacity = (0.28 + 0.06 * Math.sin(t * 5)).toFixed(3);
      },
    });
  },
  render(t) { this.s.render(t); },
});
